const req = $('Webhook: list-issues').first().json.body || {};
const limit = Math.min(req.limit || 5, 8);

const statusOf = (names) => {
  if (names.includes('fix-failed')) return 'fix-failed';
  if (names.includes('needs-review')) return 'needs-review';
  if (names.includes('WIP')) return 'WIP';
  return 'reported';
};

const sevOf = (labels) => {
  const found = labels.find(l => (l.name || '').startsWith('sev:'));
  return found ? found.name.slice(4) : 'medium';
};

const rawItems = $input.all().map(i => i.json).filter(i => i && i.number && !i.pull_request);

let issues = rawItems.map(i => {
  const labelNames = (i.labels || []).map(l => l.name);
  return {
    number: i.number,
    title: i.title,
    severity: sevOf(i.labels || []),
    status: statusOf(labelNames)
  };
});

const want = {
  wip: 'WIP',
  review: 'needs-review',
  failed: 'fix-failed',
  reported: 'reported'
}[(req.status || '').toLowerCase()];

if (want) {
  issues = issues.filter(i => i.status === want);
}

issues = issues.slice(0, limit);

const say = {
  reported: 'not started',
  WIP: 'being fixed',
  'needs-review': 'fix ready for review',
  'fix-failed': 'last fix failed'
};

const spoken = issues.length
  ? `${issues.length} issue${issues.length > 1 ? 's' : ''}. ` + issues.map(i => `Issue ${i.number}, ${i.title}, ${i.severity} severity, ${say[i.status] || 'not started'}.`).join(' ')
  : 'No matching open issues.';

return [{
  json: {
    ok: true,
    count: issues.length,
    issues,
    spoken
  }
}];
